//! Ruby SDK emitter — OpenSDK IR → generated Ruby SDK code (Rust port of
//! `@xyd-js/opensdk-ruby`, S6+ W7). Emits the FULL generated file tree: gemspec,
//! entrypoint, client, models, per-resource files, the vendored net/http
//! transport runtime (`lib/<pkg>/transport.rb`), and the SDK's own minitest
//! suite (`test/test_helper.rb` + `test/test_<resource>.rb`).
//!
//! Faithful to the framework orchestrator capability order (project → client →
//! types → resources → runtime → tests): the `# Code generated by opensdk.
//! DO NOT EDIT.` ownership header is prepended (+ one blank line) to every
//! `.rb` file, and NOT to the `.gemspec` (unknown extension).

mod cli;
mod client;
mod docs;
mod example;
mod example_plan;
mod model;
mod naming;
mod plan;
mod project;
mod rbtype;
mod runtime;
mod service;
mod tests_gen;
mod type_plan;
mod writer;

use serde_json::Value;
use std::collections::{BTreeMap, HashMap};

use naming::{pascal_case, ruby_gem_name, screaming_snake_case};

pub use docs::{generate_ruby_type_reference, generate_ruby_usage};
/// Ruby's identifier casing. Public so the e2e offline binding guard
/// (`tests/e2e_binding.rs`) builds its call key from the SAME helper the
/// emitter uses for `attr_reader` / method names — a copy there would drift
/// from the client-access shape it is supposed to describe.
pub use naming::snake_case;

pub(crate) struct Resolved {
    pkg: String,
    module_name: String,
    base_url: String,
    env_var: String,
}

/// `emitterOptions` over the spec-derived defaults (mirrors `emitter.ts`'s
/// `resolveOptions`). `options` is the TS options bag as JSON; `Value::Null`
/// means none were supplied, and every field falls back to what it derived
/// before options existed — so the no-options path is byte-identical.
///
/// `envVar` is deliberately NOT an option: like the JS emitter it derives from
/// the RESOLVED `pkg`, so a `packageName` override moves the env var with it.
pub(crate) fn resolve_options(spec: &Value, options: &Value) -> Resolved {
    use xyd_opensdk_core::emitter::opt_str;

    let title = spec
        .get("info")
        .and_then(|i| i.get("title"))
        .and_then(|t| t.as_str())
        .unwrap_or("");
    let pkg = opt_str(options, "packageName")
        .map(str::to_string)
        .unwrap_or_else(|| ruby_gem_name(title));
    let module_name = opt_str(options, "moduleName")
        .map(str::to_string)
        .unwrap_or_else(|| pascal_case(title));
    let base_url = opt_str(options, "baseURL")
        .map(str::to_string)
        .unwrap_or_else(|| {
            spec.get("servers")
                .and_then(|s| s.as_array())
                .and_then(|a| a.first())
                .and_then(|s| s.as_str())
                .unwrap_or("")
                .to_string()
        });
    let env_var = spec
        .get("security")
        .and_then(|s| s.as_array())
        .and_then(|arr| {
            arr.iter().find_map(|s| {
                s.get("envVar")
                    .and_then(|e| e.as_str())
                    .filter(|e| !e.is_empty())
            })
        })
        .map(|e| e.to_string())
        .unwrap_or_else(|| format!("{}_API_KEY", screaming_snake_case(&pkg)));
    Resolved {
        pkg,
        module_name,
        base_url,
        env_var,
    }
}

/// Prepend the ownership header to `.rb` files (+ blank line); `.gemspec` and
/// other unknown extensions are left untouched.
// The header text + per-extension comment table live in xyd_opensdk_core. The
// shared table is wider than this crate's old gate, but provably output-neutral:
// the only other extension in these goldens is one the table does not cover.
// NOTE: this now applies the header exactly ONCE (the shared helper skips
// content that already starts with it). Ruby's old copy had no such guard.
// Verified inert: all 370 .rb goldens carry exactly one header line.
fn with_header(path: &str, content: String) -> String {
    xyd_opensdk_core::header::with_file_header(path, content)
}

/// Generate the Ruby SDK's full generated file map (path → content), including
/// the vendored transport runtime and the SDK's own minitest suite.
///
/// A spec with a root `x-cli` block is CLI-mode: the generated SDK spawns the
/// real CLI binary instead of speaking HTTP (see `cli.rs`).
///
/// Equivalent to [`generate_ruby_with`] with no emitter options.
pub fn generate_ruby(spec: &Value) -> BTreeMap<String, String> {
    generate_ruby_with(spec, &Value::Null)
}

/// [`generate_ruby`] honoring `emitterOptions` (`packageName`, `moduleName`,
/// `baseURL`, `tests`). Pass `Value::Null` for none.
///
/// `packageName` moves generated PATHS (`<pkg>.gemspec`, `lib/<pkg>/**`) as well
/// as the default API-key env var — that is intended, and matches the JS emitter.
pub fn generate_ruby_with(spec: &Value, options: &Value) -> BTreeMap<String, String> {
    if xyd_opensdk_cli_common::is_cli_spec(spec) {
        return cli::generate_cli(spec);
    }
    let opts = resolve_options(spec, options);
    let types: HashMap<String, Value> = spec
        .get("types")
        .and_then(|t| t.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|t| {
                    t.get("name")
                        .and_then(|n| n.as_str())
                        .map(|n| (n.to_string(), t.clone()))
                })
                .collect()
        })
        .unwrap_or_default();

    let mut files: BTreeMap<String, String> = BTreeMap::new();
    let mut put = |path: String, content: String| {
        let c = with_header(&path, content);
        files.insert(path, c);
    };

    // generateProject
    put(
        format!("{}.gemspec", opts.pkg),
        project::render_gemspec(spec, &opts.pkg),
    );
    put(
        format!("lib/{}.rb", opts.pkg),
        project::render_entrypoint(spec, &opts.pkg),
    );
    // generateClient
    put(
        format!("lib/{}/client.rb", opts.pkg),
        client::render_client_file(spec, &opts.module_name, &opts.env_var),
    );
    // generateTypes
    put(
        format!("lib/{}/models.rb", opts.pkg),
        model::render_models_file(spec, &opts.module_name),
    );
    // generateResources
    if let Some(resources) = spec.get("resources").and_then(|r| r.as_array()) {
        for resource in resources {
            let (path, content) =
                service::render_service_file(resource, &opts.module_name, &opts.pkg, &types);
            put(path, content);
        }
    }
    // generateRuntime — the vendored net/http transport.
    put(
        format!("lib/{}/transport.rb", opts.pkg),
        runtime::render_transport_file(spec, &opts.module_name, &opts.pkg, &opts.base_url),
    );
    // generateTests — the SDK's own minitest suite (skipped when there are no
    // resources, matching the JS emitter). Opt out with
    // `emitterOptions.tests === false`.
    if xyd_opensdk_core::emitter::emit_tests(options) {
        if let Some(resources) = spec
            .get("resources")
            .and_then(|r| r.as_array())
            .filter(|r| !r.is_empty())
        {
            put(
                "test/test_helper.rb".to_string(),
                tests_gen::test_helper_rb(&opts.module_name, &opts.pkg),
            );
            for resource in resources {
                let name = resource.get("name").and_then(|n| n.as_str()).unwrap_or("");
                put(
                    format!("test/test_{}.rb", snake_case(name)),
                    tests_gen::resource_test_rb(resource, &opts.module_name, &types),
                );
            }
        }
    }

    files
}

/// This crate as plain data, for a Rust-side dispatcher and the A2 docs surface.
///
/// Additive only: no call site today, and the two docs slots are `None` until A2
/// implements them. See `xyd_opensdk_core::emitter` for why this is a data
/// descriptor rather than a trait.
pub const EMITTER: xyd_opensdk_core::emitter::EmitterFns =
    xyd_opensdk_core::emitter::EmitterFns::new("ruby", generate_ruby)
        .with_docs(generate_ruby_usage, generate_ruby_type_reference);

/// The generated file map WITH per-file write semantics.
///
/// The regen-safety contract: `skipIfExists` protects a user-owned scaffold,
/// `mergeJson` deep-merges into the user's file. The flat [`generate_ruby`]
/// above stays the byte-exact source of content; this only pairs it with the
/// shared write-mode table.
pub fn generate_ruby_files(
    spec: &serde_json::Value,
    options: &serde_json::Value,
) -> std::collections::BTreeMap<String, xyd_opensdk_core::emitter::GeneratedFile> {
    xyd_opensdk_core::emitter::attach_write_modes("ruby", generate_ruby_with(spec, options))
}
